<?php
/**
 * Builds the sitemap HTML for the shortcode and the block.
 *
 * Every value is escaped where it is printed. Lists generated by WordPress core
 * (pages, archives, authors) go through wp_kses_post(), which keeps their classes
 * and aria-current but strips anything unsafe stored in titles or names.
 *
 * @package Parich_Accessible_Sitemap
 */

if (!defined('ABSPATH')) {
	exit;
}

class Parich_Sitemap_Renderer
{
	/**
	 * Values accepted by the "sort" attribute: the union of what pages, posts,
	 * terms and authors understand. Anything else falls back to the default order.
	 */
	const SORT_VALUES = array(
		'post_title', 'post_date', 'post_modified', 'post_name', 'post_author', 'menu_order', 'ID',
		'title', 'name', 'date', 'modified', 'author', 'comment_count', 'parent',
		'id', 'term_id', 'slug', 'count', 'term_group',
		'email', 'url', 'registered', 'user_login', 'post_count', 'display_name', 'nicename',
	);

	const DEFAULT_POST_TEMPLATE = '<a href="{permalink}">{title}</a>';

	/** Shortcode attributes that rename a built-in section, e.g. pages_title="หน้าเว็บไซต์". */
	const TITLE_ATTRIBUTES = array(
		'page' => 'pages_title',
		'post' => 'posts_title',
		'category' => 'categories_title',
		'tag' => 'tags_title',
		'archive' => 'archives_title',
		'author' => 'authors_title',
	);

	/** HTML allowed in the "how to display posts" template. */
	const POST_TEMPLATE_TAGS = array(
		'a' => array('href' => true, 'title' => true, 'class' => true, 'rel' => true),
		'strong' => array('class' => true),
		'em' => array('class' => true),
		'b' => array('class' => true),
		'i' => array('class' => true),
		'span' => array('class' => true),
		'br' => array(),
	);

	/** Posts loaded in full at a time; each batch leaves the object cache before the next. */
	const BATCH_SIZE = 500;

	/** Bump when the cached sections change shape, order or format. 2: Thai order; 3: markup compressed per section. */
	const CACHE_SCHEMA = 3;

	/**
	 * "sort" values that make WordPress order terms by something other than their
	 * name; with any other value, or none, terms are ordered by name.
	 */
	const TERM_SORT_NOT_BY_NAME = array('term_id', 'id', 'slug', 'term_group', 'count', 'parent');

	/** Increases whenever posts, terms or users change; cached sitemaps of an older version are rebuilt. */
	const CACHE_VERSION_OPTION = 'parich_sitemap_cache_version';

	/** Counts rendered sitemaps so every id on the page stays unique. */
	private static $instance = 0;

	/** This request has raised the cache version. */
	private static $cache_bumped = false;

	/** A cached sitemap was read or stored since the last raise. */
	private static $cache_used = false;

	/** A raise is queued for the end of the request. */
	private static $cache_bump_queued = false;

	/** Parsed shortcode/block arguments. */
	private $args;

	/** Plugin settings (see get_settings()). */
	private $settings;

	/** IDs excluded from pages, posts and custom post types (see exclude_ids()). */
	private $exclude_ids = null;

	private $post_template;

	/**
	 * Renders the sitemap.
	 *
	 * @param array  $atts               Shortcode attributes (see parse_args()).
	 * @param string $wrapper_attributes Attributes of the wrapper element, already escaped.
	 * @return string HTML, or '' when there is nothing to list.
	 */
	public static function render($atts = array(), $wrapper_attributes = 'class="parich-sitemap"')
	{
		$renderer = new self(self::parse_args($atts), self::get_settings());
		return $renderer->build($wrapper_attributes);
	}

	/**
	 * Normalizes shortcode attributes; unknown sort/order values are dropped.
	 */
	public static function parse_args($atts)
	{
		$atts = shortcode_atts(
			array(
				'only' => '',
				'display_title' => true,
				'display_category_title_wording' => true,
				'only_private' => false,
				'sort' => '',
				'order' => '',
				'heading_level' => 2,
				'toc' => true,
				'posts_per_category' => '',
				'collapsible' => '',
			) + array_fill_keys(self::TITLE_ATTRIBUTES, ''),
			(array) $atts,
			'parich_sitemap'
		);

		$order = strtoupper(trim((string) $atts['order']));

		$titles = array();
		foreach (self::TITLE_ATTRIBUTES as $key => $attribute) {
			$titles[$key] = is_string($atts[$attribute]) ? sanitize_text_field($atts[$attribute]) : '';
		}

		return array(
			'titles' => $titles,
			'only' => sanitize_key((string) $atts['only']),
			'display_title' => self::to_bool($atts['display_title'], true),
			'category_prefix' => self::to_bool($atts['display_category_title_wording'], true),
			'only_private' => self::to_bool($atts['only_private'], false),
			'sort' => in_array($atts['sort'], self::SORT_VALUES, true) ? $atts['sort'] : null,
			'order' => in_array($order, array('ASC', 'DESC'), true) ? $order : null,
			// Headings must fit the page outline (WCAG 1.3.1 / 2.4.6): h2–h6, h2 when invalid.
			'heading_level' => is_numeric($atts['heading_level']) ? max(2, min(6, (int) $atts['heading_level'])) : 2,
			'toc' => self::to_bool($atts['toc'], true),
			// Empty: use the setting. 0: every post.
			'posts_per_category' => is_numeric($atts['posts_per_category']) ? max(0, min(1000, (int) $atts['posts_per_category'])) : null,
			'collapsible' => self::parse_collapsible($atts['collapsible']),
		);
	}

	/**
	 * Collapsible categories: '' (no), 'open' (collapsible, expanded at first — the
	 * safer start: find-in-page and screen readers reach everything) or 'closed'.
	 */
	private static function parse_collapsible($value)
	{
		$value = strtolower(trim(is_scalar($value) ? (string) $value : ''));
		if ('closed' === $value) {
			return 'closed';
		}
		return in_array($value, array('open', 'true', '1', 'yes', 'on'), true) ? 'open' : '';
	}

	public static function get_settings()
	{
		$defaults = Parich_Sitemap_Settings::defaults();
		$get = function ($name) use ($defaults) {
			return get_option($name, $defaults[$name]);
		};
		return array(
			// Parts of the full sitemap switched off: any of page, post, archive, author.
			'excluded_sections' => (array) $get('parich_sitemap_excluded_sections'),
			'excluded_post_types' => (array) $get('parich_sitemap_excluded_post_types'),
			'excluded_taxonomies' => (array) $get('parich_sitemap_excluded_taxonomies'),
			'exclude_ids' => wp_parse_id_list($get('parich_sitemap_exclude_pages')),
			'exclude_password_protected' => (bool) $get('parich_sitemap_exclude_password_protected'),
			'nofollow' => (bool) $get('parich_sitemap_add_nofollow'),
			'post_multiple_times' => (bool) $get('parich_sitemap_display_post_multiple_times'),
			'post_template' => (string) $get('parich_sitemap_post_template'),
			'buddhist_era' => (bool) $get('parich_sitemap_buddhist_era'),
			'posts_per_category' => max(0, (int) $get('parich_sitemap_posts_per_category')),
		);
	}

	/**
	 * Shortcode booleans: like the original plugin, only an explicit "false"
	 * turns off a default-on option and only an explicit "true" turns on a default-off one.
	 */
	private static function to_bool($value, $default)
	{
		if (is_bool($value)) {
			return $value;
		}
		$value = strtolower(trim((string) $value));
		return $default ? !in_array($value, array('false', '0', 'no', 'off'), true) : in_array($value, array('true', '1', 'yes', 'on'), true);
	}

	private function __construct(array $args, array $settings)
	{
		$this->args = $args;
		$this->settings = $settings;

		$template = trim($settings['post_template']) !== '' ? $settings['post_template'] : self::DEFAULT_POST_TEMPLATE;
		$this->post_template = wp_kses($template, self::POST_TEMPLATE_TAGS);
	}

	/**
	 * IDs to leave out: from the settings, plus password-protected content when that
	 * is hidden. Worked out on first use, so a cached sitemap costs no query for it.
	 */
	private function exclude_ids()
	{
		if (null === $this->exclude_ids) {
			$ids = $this->settings['exclude_ids'];
			if ($this->settings['exclude_password_protected']) {
				global $wpdb;
				// No WP_Query argument selects "has a password"; the result ends up in the cached sitemap.
				// phpcs:ignore WordPress.DB.DirectDatabaseQuery.DirectQuery, WordPress.DB.DirectDatabaseQuery.NoCaching
				$protected = $wpdb->get_col("SELECT ID FROM {$wpdb->posts} WHERE post_status = 'publish' AND post_password <> ''");
				$ids = array_merge($ids, array_map('intval', $protected));
			}
			$this->exclude_ids = array_values(array_unique($ids));
		}
		return $this->exclude_ids;
	}

	private function posts_per_category()
	{
		return $this->args['posts_per_category'] ?? $this->settings['posts_per_category'];
	}

	/**
	 * Sections from the cache when they are current, otherwise built and stored.
	 *
	 * What is cached is the list of sections before ids, the table of contents and
	 * aria-current are added, so those stay right for every page and every instance.
	 * One transient per set of options (its name does not change with the content),
	 * so rebuilding overwrites it instead of leaving old copies behind.
	 */
	private function cached_sections()
	{
		// Private pages depend on who is looking: never cached.
		$use_cache = !$this->args['only_private'] && apply_filters('parich_sitemap_use_cache', true, $this->args);
		if (!$use_cache) {
			return $this->collect_sections();
		}

		self::$cache_used = true;
		$key = $this->cache_key();
		$version = (int) get_option(self::CACHE_VERSION_OPTION, 0);
		$cached = get_transient($key);
		if (is_array($cached) && isset($cached['version'], $cached['data']) && $cached['version'] === $version) {
			$sections = self::unpack($cached['data']);
			if (is_array($sections)) {
				return $sections;
			}
		}

		$sections = $this->collect_sections();
		set_transient($key, array('version' => $version, 'data' => self::pack($sections)), (int) apply_filters('parich_sitemap_cache_ttl', DAY_IN_SECONDS));
		return $sections;
	}

	/**
	 * Each section's list markup compressed and hex-encoded ("gz:…"): several times
	 * smaller, and a big sitemap stored as plain HTML makes the INSERT query so long
	 * that wpdb's table-name regex runs out of backtracking (a PHP deprecation notice
	 * on every rebuild). Plain markup ("html:…") when PHP has no zlib. The array
	 * itself is stored by the transients API.
	 */
	private static function pack(array $sections)
	{
		return array_map(function ($section) {
			$section['items'] = function_exists('gzcompress') ? 'gz:' . bin2hex(gzcompress($section['items'], 6)) : 'html:' . $section['items'];
			return $section;
		}, $sections);
	}

	/** @return array|null Sections, or null when the data is unreadable. */
	private static function unpack($packed)
	{
		if (!is_array($packed)) {
			return null;
		}
		$sections = array();
		foreach ($packed as $section) {
			if (!is_array($section) || !isset($section['key'], $section['title'], $section['items']) || !is_string($section['items'])) {
				return null;
			}
			list($format, $data) = array_pad(explode(':', $section['items'], 2), 2, '');
			if ('gz' === $format) {
				$is_hex = '' !== $data && 0 === strlen($data) % 2 && strspn($data, '0123456789abcdef') === strlen($data);
				$data = $is_hex && function_exists('gzuncompress') ? gzuncompress(hex2bin($data)) : false;
			} elseif ('html' !== $format) {
				$data = false;
			}
			if (!is_string($data)) {
				return null;
			}
			$section['items'] = $data;
			$sections[] = $section;
		}
		return $sections;
	}

	/**
	 * Everything the output depends on apart from the content itself, which is
	 * covered by the cache version.
	 */
	private function cache_key()
	{
		return 'parich_sitemap_' . md5((string) wp_json_encode(array(
			self::CACHE_SCHEMA,
			filemtime(__FILE__), // A plugin update rebuilds the cache.
			$this->args,
			$this->settings,
			get_locale(),
			get_option('date_format'),
			wp_timezone_string(),
			get_option('permalink_structure'),
			home_url(),
		)));
	}

	/**
	 * Marks every cached sitemap as outdated. Hooked to post, term, post-term and
	 * user changes. The first change in a request raises the version at once;
	 * further changes (a bulk import, say) raise it once more at the end of the
	 * request instead of every time — or at once if a sitemap was rendered in between.
	 */
	public static function flush_cache()
	{
		if (!self::$cache_bumped || self::$cache_used) {
			self::bump_cache_version();
		} elseif (!self::$cache_bump_queued) {
			self::$cache_bump_queued = true;
			add_action('shutdown', array(__CLASS__, 'bump_cache_version'));
		}
	}

	public static function bump_cache_version()
	{
		update_option(self::CACHE_VERSION_OPTION, (int) get_option(self::CACHE_VERSION_OPTION, 0) + 1, true);
		self::$cache_bumped = true;
		self::$cache_used = false;
	}

	/**
	 * Markup:
	 *   <nav aria-label="Sitemap">            navigation landmark (1.3.1, 2.4.1)
	 *     <p id=…-toc>On this page:</p>       table of contents when there are 2+ headed sections (2.4.1)
	 *     <ul aria-labelledby=…-toc>…</ul>
	 *     <div class="parich-sitemap__section">  one per section, not <section> (no extra landmarks)
	 *       <hN id=…>Pages</hN>               level from heading_level (2.4.6)
	 *       <ul>…</ul>                        nested lists carry the hierarchy (1.3.1)
	 *       <p><a href=#…-toc>Back to contents</a></p>  with the table of contents only
	 */
	private function build($wrapper_attributes)
	{
		$sections = $this->cached_sections();
		if (!$sections) {
			return '';
		}

		$prefix = 'parich-sitemap-' . (++self::$instance);
		$level = $this->args['heading_level'];
		$show_titles = $this->args['display_title'];

		$label = $this->args['only'] === ''
			? __('Sitemap', 'parich-accessible-sitemap')
			/* translators: %s: section title, e.g. "Pages" */
			: sprintf(__('Sitemap: %s', 'parich-accessible-sitemap'), $sections[0]['title']);

		$html = '<nav ' . $wrapper_attributes . ' aria-label="' . esc_attr($label) . "\">\n";

		$toc = $show_titles && $this->args['toc'] && count($sections) > 1;
		if ($toc) {
			$html .= '<p class="parich-sitemap__toc-label" id="' . esc_attr($prefix . '-toc') . '">' . esc_html__('On this page:', 'parich-accessible-sitemap') . "</p>\n";
			// role="list" keeps list semantics in Safari/VoiceOver when list-style is removed.
			$html .= '<ul class="parich-sitemap__toc" role="list" aria-labelledby="' . esc_attr($prefix . '-toc') . "\">\n";
			foreach ($sections as $section) {
				$html .= '<li><a href="#' . esc_attr($this->section_id($prefix, $section)) . '">' . esc_html($section['title']) . "</a></li>\n";
			}
			$html .= "</ul>\n";
		}

		foreach ($sections as $section) {
			$key = sanitize_html_class($section['key']);
			$html .= '<div class="parich-sitemap__section parich-sitemap__section--' . esc_attr($key) . "\">\n";
			if ($show_titles) {
				$html .= sprintf(
					'<h%1$d class="parich-sitemap__heading" id="%2$s">%3$s</h%1$d>' . "\n",
					$level,
					esc_attr($this->section_id($prefix, $section)),
					esc_html($section['title'])
				);
			}
			$html .= '<ul class="parich-sitemap__list parich-sitemap__list--' . esc_attr($key) . "\">\n";
			$html .= $section['items'];
			$html .= "</ul>\n";
			if ($toc) {
				// Back to the other sections from the end of a long one, without scrolling (2.4.1).
				$html .= '<p class="parich-sitemap__back"><a href="#' . esc_attr($prefix . '-toc') . '">' . esc_html__('Back to contents', 'parich-accessible-sitemap') . "</a></p>\n";
			}
			$html .= "</div>\n";
		}
		$html .= "</nav>\n";

		return $this->finalize_links($html);
	}

	private function section_id($prefix, array $section)
	{
		return $prefix . '-' . sanitize_html_class($section['key']);
	}

	/**
	 * @return array[] Non-empty sections: array('key' => ..., 'title' => ..., 'items' => '<li>...').
	 */
	private function collect_sections()
	{
		// The "only" attribute wins over the exclusions in the settings, as in the original plugin.
		switch ($this->args['only']) {
			case 'page':
				return $this->keep(array($this->section_pages()));
			case 'post':
				return $this->keep(array($this->section_posts_by_category()));
			case 'category':
				return $this->keep(array($this->section_categories()));
			case 'tag':
				return $this->keep(array($this->section_tags()));
			case 'archive':
				return $this->keep(array($this->section_archives()));
			case 'author':
				return $this->keep(array($this->section_authors()));
			case '':
				break;
			default:
				// Only public content types; the original also listed non-public ones (templates, menus, ...).
				$post_type = get_post_type_object($this->args['only']);
				if ($post_type && $post_type->public) {
					return $this->keep(array($this->section_post_type($post_type, true)));
				}
				$taxonomy = get_taxonomy($this->args['only']);
				if ($taxonomy && $taxonomy->public) {
					return $this->keep(array($this->section_taxonomy($taxonomy)));
				}
				return array();
		}

		$excluded = $this->settings['excluded_sections'];
		$sections = array();

		if (!in_array('page', $excluded, true)) {
			$sections[] = $this->section_pages();
		}
		if (!in_array('post', $excluded, true)) {
			$sections[] = $this->section_posts_by_category();
		}
		foreach (get_post_types(array('public' => true, '_builtin' => false), 'objects') as $post_type) {
			if (!in_array($post_type->name, $this->settings['excluded_post_types'], true)) {
				$sections[] = $this->section_post_type($post_type, false);
			}
		}
		foreach (get_taxonomies(array('public' => true, '_builtin' => false), 'objects') as $taxonomy) {
			if (!in_array($taxonomy->name, $this->settings['excluded_taxonomies'], true)) {
				$sections[] = $this->section_taxonomy($taxonomy);
			}
		}
		if (!in_array('archive', $excluded, true)) {
			$sections[] = $this->section_archives();
		}
		if (!in_array('author', $excluded, true)) {
			$sections[] = $this->section_authors();
		}

		return $this->keep($sections);
	}

	private function keep(array $sections)
	{
		return array_values(array_filter($sections));
	}

	/**
	 * @param string $title Default title; replaced by a *_title attribute for built-in sections.
	 */
	private function section($key, $title, $items)
	{
		if (trim($items) === '') {
			return null;
		}
		if (!empty($this->args['titles'][$key])) {
			$title = $this->args['titles'][$key];
		}
		return array('key' => $key, 'title' => $title, 'items' => $items);
	}

	private function section_pages()
	{
		$args = array(
			'title_li' => '',
			'echo' => 0,
		);
		if ($this->args['sort']) {
			$args['sort_column'] = $this->args['sort'];
		}
		if ($this->exclude_ids()) {
			// The pages excluded in the settings (a short list); the sitemap is cached.
			$args['exclude'] = implode(',', $this->exclude_ids()); // phpcs:ignore WordPressVIPMinimum.Performance.WPQueryParams.PostNotIn_exclude
		}
		if ($this->args['only_private']) {
			// The original listed private pages to every visitor.
			if (!current_user_can('read_private_pages')) {
				return null;
			}
			$args['post_status'] = 'private';
		}

		// Pages ordered by title — by default (menu order, then title) or with
		// sort="post_title|title" — list Thai titles in dictionary order.
		$sort = $this->args['sort'];
		$by_title = null === $sort || in_array($sort, array('post_title', 'title'), true);
		$thai_order = function ($pages) use ($sort) {
			$menu_order = null === $sort ? function ($page) {
				return (int) $page->menu_order;
			} : null;
			return Parich_Sitemap_Thai_Sort::sort((array) $pages, function ($page) {
				return $page->post_title;
			}, false, $menu_order);
		};
		if ($by_title) {
			add_filter('get_pages', $thai_order);
		}
		$list = (string) wp_list_pages($args);
		if ($by_title) {
			remove_filter('get_pages', $thai_order);
		}

		return $this->section('page', __('Pages', 'parich-accessible-sitemap'), wp_kses_post($list));
	}

	/**
	 * Terms ordered by name (the default) with Thai names in dictionary order.
	 *
	 * @param WP_Term[]|WP_Error $terms
	 * @param string|null        $sort  The "sort" the terms were queried with.
	 * @return WP_Term[]
	 */
	private function thai_terms($terms, $sort = null)
	{
		if (!is_array($terms)) {
			return array();
		}
		if (null !== $sort && in_array(strtolower($sort), self::TERM_SORT_NOT_BY_NAME, true)) {
			return $terms;
		}
		return Parich_Sitemap_Thai_Sort::sort($terms, function ($term) {
			return $term->name;
		});
	}

	private function section_posts_by_category()
	{
		$term_args = array();
		// Like the original, "sort" orders both the categories and the posts inside them.
		if ($this->args['sort']) {
			$term_args['orderby'] = $this->args['sort'];
		}
		$categories = $this->thai_terms(get_categories($term_args), $this->args['sort']);

		$parents = array();
		$children = array();
		foreach ($categories as $category) {
			$parents[(int) $category->term_id] = (int) $category->parent;
			$children[(int) $category->parent][] = $category;
		}

		$query = array('post_type' => 'post');
		if ($this->args['sort']) {
			$query['orderby'] = $this->args['sort'];
		}
		if ($this->args['order']) {
			$query['order'] = $this->args['order'];
		}

		// One pass over every post, in display order. The original ran one query per
		// category — each also returning the posts of its sub-categories — and kept the
		// matches; the placement rules below are the same, worked out in PHP.
		$limit = $this->posts_per_category();
		$lines = array();   // post ID => formatted line (only for posts that are shown)
		$listed = array();  // category ID => post IDs shown, in display order
		$placed = array();  // category ID => every post ID placed there, shown or not
		$this->each_post($this->post_ids($query), 'post', function (WP_Post $post) use ($parents, $limit, &$lines, &$listed, &$placed) {
			// Categories whose query returned the post: its own and all their ancestors.
			$reach = array();
			$terms = get_object_term_cache($post->ID, 'category');
			foreach (is_array($terms) ? $terms : array() as $term) {
				for ($id = (int) $term->term_id; isset($parents[$id]) && !isset($reach[$id]); $id = $parents[$id]) {
					$reach[$id] = true;
				}
			}

			if ($this->settings['post_multiple_times']) {
				$targets = array_keys($reach);
			} else {
				// Once, under its first category in get_the_category() order.
				$first = get_the_category($post->ID);
				$targets = !empty($first) && isset($reach[(int) $first[0]->term_id]) ? array((int) $first[0]->term_id) : array();
			}

			// Posts past the per-category limit are only counted, never formatted.
			$shown = false;
			foreach ($targets as $category_id) {
				$placed[$category_id][] = $post->ID;
				if (!$limit || count($placed[$category_id]) <= $limit) {
					$listed[$category_id][] = $post->ID;
					$shown = true;
				}
			}
			if ($shown) {
				$lines[$post->ID] = $this->format_post($post);
			}
		});

		return $this->section('post', __('Posts by category', 'parich-accessible-sitemap'), $this->category_items($children, 0, $listed, $lines, $placed));
	}

	/**
	 * @param array $children Category objects by parent ID.
	 * @param int   $parent_id
	 * @param array $listed   Post IDs shown, by category ID.
	 * @param array $lines    Formatted post lines by post ID.
	 * @param array $placed   Every post ID placed in each category, shown or not.
	 */
	private function category_items(array $children, $parent_id, array $listed, array $lines, array $placed)
	{
		$html = '';
		foreach ($children[$parent_id] ?? array() as $category) {
			$id = (int) $category->term_id;
			$url = esc_url(get_category_link($id));
			$link = '<a href="' . $url . '">' . esc_html($category->name) . '</a>';
			/* translators: %s: category name, linked */
			$title = $this->args['category_prefix'] ? sprintf(esc_html__('Category: %s', 'parich-accessible-sitemap'), $link) : $link;

			$posts = $listed[$id] ?? array();
			$inner = '';
			foreach ($posts as $post_id) {
				$inner .= '<li class="parich-sitemap__post">' . $lines[$post_id] . "</li>\n";
			}
			$hidden = count($placed[$id] ?? array()) - count($posts);
			if ($hidden > 0) {
				// The link names the category, so it makes sense out of context (WCAG 2.4.4).
				/* translators: 1: number of posts not listed, 2: category name */
				$more = sprintf(__('%1$d more in %2$s', 'parich-accessible-sitemap'), $hidden, $category->name);
				$inner .= '<li class="parich-sitemap__more"><a href="' . $url . '">' . esc_html($more) . "</a></li>\n";
			}
			$inner .= $this->category_items($children, $id, $listed, $lines, $placed);

			if ($this->args['collapsible']) {
				// What a visitor finds when expanding it: posts of its sub-categories count too.
				$total = count(array_unique($this->subtree_post_ids($children, $id, $placed)));
				$html .= $this->collapsible_category($category, $url, $total, $inner);
				continue;
			}

			// A <span> styled bold: the nested list already conveys the structure, <strong> would add false emphasis.
			$html .= '<li class="parich-sitemap__category"><span class="parich-sitemap__category-title">' . $title . '</span>';
			if ($inner !== '') {
				$html .= "\n<ul class=\"parich-sitemap__list\">\n" . $inner . '</ul>';
			}
			$html .= "</li>\n";
		}
		return $html;
	}

	/**
	 * Post IDs placed in a category and in all its sub-categories.
	 */
	private function subtree_post_ids(array $children, $id, array $placed)
	{
		$ids = $placed[$id] ?? array();
		foreach ($children[$id] ?? array() as $child) {
			$ids = array_merge($ids, $this->subtree_post_ids($children, (int) $child->term_id, $placed));
		}
		return $ids;
	}

	/**
	 * A category that can be collapsed: native <details>/<summary>, so it works
	 * without JavaScript and screen readers announce expanded/collapsed.
	 *
	 * The summary is plain text (a link inside a summary competes with the toggle),
	 * so the category link becomes the first item of its list — the same place in
	 * the link order as before.
	 */
	private function collapsible_category($category, $url, $total, $inner)
	{
		$name = esc_html($category->name);
		/* translators: %s: category name */
		$title = $this->args['category_prefix'] ? sprintf(esc_html__('Category: %s', 'parich-accessible-sitemap'), $name) : $name;
		/* translators: %d: number of posts in the category and its sub-categories */
		$count = sprintf(_n('(%d post)', '(%d posts)', $total, 'parich-accessible-sitemap'), $total);
		/* translators: %s: category name */
		$all = sprintf(__('All posts in %s', 'parich-accessible-sitemap'), $category->name);

		return '<li class="parich-sitemap__category"><details' . ('open' === $this->args['collapsible'] ? ' open' : '') . ">\n"
			. '<summary><span class="parich-sitemap__category-title">' . $title . '</span> <span class="parich-sitemap__count">' . esc_html($count) . "</span></summary>\n"
			. "<ul class=\"parich-sitemap__list\">\n"
			. '<li class="parich-sitemap__category-link"><a href="' . $url . '">' . esc_html($all) . "</a></li>\n"
			. $inner
			. "</ul>\n</details></li>\n";
	}

	/**
	 * IDs of the posts to list, in display order: one query, no post data. Same
	 * defaults as get_posts() in the original (published, sticky posts not moved).
	 */
	private function post_ids(array $query)
	{
		$query['numberposts'] = -1;
		$query['fields'] = 'ids';
		if ($this->exclude_ids()) {
			// The IDs excluded in the settings (a short list); the sitemap is cached.
			$query['exclude'] = $this->exclude_ids(); // phpcs:ignore WordPressVIPMinimum.Performance.WPQueryParams.PostNotIn_exclude
		}
		$ids = array_map('intval', get_posts($query));

		// Sorted by title: Thai titles in dictionary order, same direction (posts default to DESC).
		if (isset($query['orderby']) && in_array($query['orderby'], array('title', 'post_title'), true)) {
			$titles = $this->post_titles($ids);
			$ids = Parich_Sitemap_Thai_Sort::sort($ids, function ($id) use ($titles) {
				return $titles[$id] ?? '';
			}, 'ASC' !== strtoupper($query['order'] ?? 'DESC'));
		}
		return $ids;
	}

	/**
	 * Raw titles by post ID, for sorting: a light query per 1,000 posts, no post data loaded.
	 *
	 * @param int[] $ids
	 * @return string[]
	 */
	private function post_titles(array $ids)
	{
		global $wpdb;
		$titles = array();
		foreach (array_chunk($ids, 1000) as $chunk) {
			// Titles only: WP_Query would load every post in full. The sorted result is cached.
			// phpcs:ignore WordPress.DB.DirectDatabaseQuery.DirectQuery, WordPress.DB.DirectDatabaseQuery.NoCaching
			$rows = $wpdb->get_results(
				$wpdb->prepare(
					"SELECT ID, post_title FROM {$wpdb->posts} WHERE ID IN (" . implode(',', array_fill(0, count($chunk), '%d')) . ')',
					$chunk
				)
			);
			foreach ($rows as $row) {
				$titles[(int) $row->ID] = (string) $row->post_title;
			}
		}
		return $titles;
	}

	/**
	 * Calls $each for every post, a batch at a time, with the batch's posts and terms
	 * in the object cache — so get_permalink(), get_the_category() and the like run
	 * no queries of their own — and drops the posts it loaded from the cache again
	 * after each batch, so memory stays flat however many posts there are.
	 *
	 * Posts are loaded without their content (about ten times faster: titles and links
	 * need none of it). Those partial posts are only ever put in a request-local cache;
	 * with a persistent object cache, which other requests read, full posts are loaded.
	 *
	 * @param int[]    $ids
	 * @param string   $post_type For priming the term cache.
	 * @param callable $each      function (WP_Post $post)
	 */
	private function each_post(array $ids, $post_type, callable $each)
	{
		global $wpdb;
		$partial = !wp_using_ext_object_cache();

		foreach (array_chunk($ids, self::BATCH_SIZE) as $batch) {
			$loaded = _get_non_cached_ids($batch, 'posts');
			if ($loaded && $partial) {
				// Posts without their content (see above); they go into the object cache just below.
				// phpcs:ignore WordPress.DB.DirectDatabaseQuery.DirectQuery, WordPress.DB.DirectDatabaseQuery.NoCaching
				$rows = $wpdb->get_results(
					$wpdb->prepare(
						"SELECT ID, post_author, post_date, post_date_gmt, post_title, post_status, post_name, post_modified, post_modified_gmt, post_parent, post_type, menu_order, post_mime_type, comment_count
						FROM {$wpdb->posts} WHERE ID IN (" . implode(',', array_fill(0, count($loaded), '%d')) . ')',
						$loaded
					)
				);
				foreach ($rows as $row) {
					$row->filter = 'raw';
					wp_cache_add($row->ID, $row, 'posts');
				}
			} elseif ($loaded) {
				_prime_post_caches($loaded, false, false);
			}
			update_object_term_cache($batch, $post_type);

			foreach ($batch as $id) {
				$post = get_post($id);
				if ($post) {
					$each($post);
				}
			}

			foreach ($loaded as $id) {
				wp_cache_delete($id, 'posts');
			}
		}
	}

	/**
	 * Fills the post template. Each placeholder is escaped for where it can appear
	 * (text or attribute); unknown placeholders are left as they are.
	 */
	private function format_post(WP_Post $post)
	{
		return preg_replace_callback('/\{([a-z_]+)\}/i', function ($matches) use ($post) {
			switch (strtolower($matches[1])) {
				case 'title':
					return esc_html($this->post_title($post));
				case 'permalink':
					return esc_url(get_permalink($post));
				case 'date':
					return esc_html($this->format_date(get_option('date_format'), $post));
				case 'year':
					return esc_html($this->format_date('Y', $post));
				case 'monthnum':
					return esc_html(get_the_time('m', $post));
				case 'day':
					return esc_html(get_the_time('d', $post));
				case 'hour':
					return esc_html(get_the_time('H', $post));
				case 'minute':
					return esc_html(get_the_time('i', $post));
				case 'second':
					return esc_html(get_the_time('s', $post));
				case 'post_id':
					return (string) (int) $post->ID;
				case 'category':
					$categories = get_the_category($post->ID);
					return empty($categories) ? '' : esc_html($categories[0]->name);
				default:
					return $matches[0];
			}
		}, $this->post_template);
	}

	/**
	 * wp_date() in the site's timezone and language (Thai month names come from the
	 * WordPress Thai language pack). With the Buddhist Era setting, the year format
	 * characters Y, y and o are replaced by the BE year (+543) as escaped literals,
	 * so any date format works, e.g. "j F Y" → "27 กันยายน 2569".
	 */
	private function format_date($format, WP_Post $post)
	{
		$timestamp = get_post_timestamp($post);
		if (!$timestamp) {
			return '';
		}
		if (!$this->settings['buddhist_era']) {
			return (string) wp_date($format, $timestamp);
		}

		$years = array(
			'Y' => (string) ((int) wp_date('Y', $timestamp) + 543),
			'o' => (string) ((int) wp_date('o', $timestamp) + 543),
		);
		$years['y'] = substr($years['Y'], -2);

		$converted = '';
		$length = strlen($format);
		for ($i = 0; $i < $length; $i++) {
			$char = $format[$i];
			if ($char === '\\') {
				$converted .= $char . ($format[$i + 1] ?? '');
				$i++;
			} elseif (isset($years[$char])) {
				$converted .= '\\' . implode('\\', str_split($years[$char]));
			} else {
				$converted .= $char;
			}
		}
		return (string) wp_date($converted, $timestamp);
	}

	/**
	 * Plain-text title; never empty, so every link has a name (WCAG 2.4.4).
	 */
	private function post_title(WP_Post $post)
	{
		// Core's filter, applied the way wp_list_pages() does it.
		$title = trim(wp_strip_all_tags(apply_filters('the_title', $post->post_title, $post->ID))); // phpcs:ignore WordPress.NamingConventions.PrefixAllGlobals.NonPrefixedHooknameFound
		if ($title === '') {
			/* translators: %d: post ID (same wording as the WordPress page list) */
			$title = sprintf(__('#%d (no title)', 'parich-accessible-sitemap'), $post->ID);
		}
		return $title;
	}

	private function section_categories()
	{
		$args = array();
		if ($this->args['sort']) {
			$args['orderby'] = $this->args['sort'];
		}

		$items = '';
		foreach ($this->thai_terms(get_categories($args), $this->args['sort']) as $category) {
			$items .= '<li><a href="' . esc_url(get_category_link($category->term_id)) . '">' . esc_html($category->name) . "</a></li>\n";
		}
		return $this->section('category', __('Categories', 'parich-accessible-sitemap'), $items);
	}

	private function section_tags()
	{
		$items = '';
		foreach ($this->thai_terms(get_tags()) as $tag) {
			$items .= '<li><a href="' . esc_url(get_tag_link($tag->term_id)) . '">' . esc_html($tag->name) . "</a></li>\n";
		}
		return $this->section('tag', __('Tags', 'parich-accessible-sitemap'), $items);
	}

	private function section_archives()
	{
		$items = wp_kses_post((string) wp_get_archives(array('echo' => 0)));
		if ($this->settings['buddhist_era']) {
			// Years in the link texts only ("กันยายน 2026" → "กันยายน 2569"); the URLs keep the real year.
			$items = preg_replace_callback('/(<a\b[^>]*>)([^<]*)(<\/a>)/', function ($link) {
				return $link[1] . preg_replace_callback('/\b(1[89]\d\d|2[01]\d\d)\b/', function ($year) {
					return (string) ((int) $year[1] + 543);
				}, $link[2]) . $link[3];
			}, $items);
		}
		return $this->section('archive', __('Archives', 'parich-accessible-sitemap'), $items);
	}

	private function section_authors()
	{
		$args = array('echo' => 0);
		if ($this->args['sort']) {
			$args['orderby'] = $this->args['sort'];
		}
		return $this->section('author', __('Authors', 'parich-accessible-sitemap'), wp_kses_post((string) wp_list_authors($args)));
	}

	/**
	 * @param WP_Post_Type $post_type
	 * @param bool         $with_sort The original applied "sort" only when the type was requested with "only".
	 */
	private function section_post_type($post_type, $with_sort)
	{
		$query = array(
			'post_type' => $post_type->name,
			'suppress_filters' => false, // As in the original, e.g. for multilingual plugins.
		);
		if ($with_sort && $this->args['sort']) {
			$query['orderby'] = $this->args['sort'];
		}

		$items = '';
		$this->each_post($this->post_ids($query), $post_type->name, function (WP_Post $post) use (&$items) {
			$items .= '<li><a href="' . esc_url(get_permalink($post)) . '">' . esc_html($this->post_title($post)) . "</a></li>\n";
		});
		return $this->section($post_type->name, $post_type->label, $items);
	}

	/**
	 * @param WP_Taxonomy $taxonomy
	 */
	private function section_taxonomy($taxonomy)
	{
		$terms = get_terms(array('taxonomy' => $taxonomy->name));
		if (is_wp_error($terms)) {
			return null;
		}

		$items = '';
		foreach ($this->thai_terms($terms) as $term) {
			$link = get_term_link($term);
			if (is_wp_error($link)) {
				continue;
			}
			$items .= '<li><a href="' . esc_url($link) . '">' . esc_html($term->name) . "</a></li>\n";
		}
		return $this->section($taxonomy->name, $taxonomy->label, $items);
	}

	/**
	 * One pass over the finished markup:
	 * - aria-current="page" on links to the page being viewed (4.1.2); wp_list_pages()
	 *   already does this for pages, this covers posts, custom types and terms.
	 * - rel="nofollow" when enabled. Done here rather than with a wp_list_pages filter,
	 *   which in the original stayed registered and leaked into other page lists.
	 */
	private function finalize_links($html)
	{
		$current = $this->current_url();
		$nofollow = $this->settings['nofollow'];
		if ($current === '' && !$nofollow) {
			return $html;
		}

		$processor = new WP_HTML_Tag_Processor($html);
		while ($processor->next_tag('a')) {
			$href = (string) $processor->get_attribute('href');
			if ($href === '' || $href[0] === '#') {
				continue;
			}
			if ($current !== '' && null === $processor->get_attribute('aria-current') && untrailingslashit($href) === $current) {
				$processor->set_attribute('aria-current', 'page');
			}
			if ($nofollow) {
				$rel = preg_split('/\s+/', trim((string) $processor->get_attribute('rel')), -1, PREG_SPLIT_NO_EMPTY);
				if (!in_array('nofollow', $rel, true)) {
					$rel[] = 'nofollow';
					$processor->set_attribute('rel', implode(' ', $rel));
				}
			}
		}
		return $processor->get_updated_html();
	}

	/**
	 * URL of the post or term being viewed, without trailing slash ('' elsewhere).
	 */
	private function current_url()
	{
		$url = '';
		if (is_singular()) {
			$url = get_permalink(get_queried_object_id());
		} elseif (is_category() || is_tag() || is_tax()) {
			$url = get_term_link(get_queried_object());
		} elseif (is_author()) {
			$url = get_author_posts_url(get_queried_object_id());
		}
		return is_string($url) && $url !== '' ? untrailingslashit($url) : '';
	}
}
